import { disablePageScroll, enablePageScroll } from "@fluejs/noscroll";

class Header extends HTMLElement {
  private megamenuWrappers: NodeListOf<HTMLElement> | null = null;
  private megamenuTriggers: NodeListOf<HTMLButtonElement> | null = null;
  private currentOpenMenu: HTMLElement | null = null;
  private animationDuration = 300;
  private mobileMenuWrapper: HTMLButtonElement | null = null;
  private searchTrigger: HTMLButtonElement | null = null;
  private searchInput: HTMLInputElement | null = null;
  private resizeTimeout: number | null = null;
  private rafId: number | null = null;
  // Transparency management
  private initialTransparent = false;

  constructor() {
    super();
  }

  connectedCallback() {
    this.initialTransparent = this.classList.contains("is-transparent");
    this.handleHeaderHeight();
    this.cacheElements();
    this.bindEvents();
    this.updateTransparency();
    this.entryListeners();

    window.addEventListener("resize", this.handleResizeDebounced.bind(this));
    window.addEventListener("scroll", this.handleStickyHeader.bind(this));
    document.addEventListener("click", this.handleOutsideClick.bind(this));
  }

  disconnectedCallback() {
    if (this.resizeTimeout) {
      clearTimeout(this.resizeTimeout);
    }
    if (this.rafId) {
      cancelAnimationFrame(this.rafId);
    }
  }

  private cacheElements(): void {
    this.searchTrigger = this.querySelector(
      "[js-header='open-search']",
    ) as HTMLButtonElement;
    this.searchInput = this.querySelector(".input-search");
    this.megamenuWrappers = this.querySelectorAll("[data-megamenu-wrapper]");
    this.megamenuTriggers = this.querySelectorAll("[data-megamenu-trigger]");
    this.mobileMenuWrapper = this.querySelector(
      "[js-header='open-mobile-menu']",
    ) as HTMLButtonElement;
  }

  private bindEvents(): void {
    if (this.megamenuTriggers) {
      this.megamenuTriggers.forEach((trigger) => {
        trigger.addEventListener("click", this.handleMegamenuClick.bind(this));
        trigger.addEventListener("keydown", this.handleKeyDown.bind(this));
      });
    }

    if (this.mobileMenuWrapper) {
      this.mobileMenuWrapper.addEventListener(
        "click",
        this.handleMobileMenuClick.bind(this),
      );
    }

    if (this.searchTrigger) {
      this.searchTrigger.addEventListener(
        "click",
        this.handleSearchClick.bind(this),
      );
    }
  }

  private handleResizeDebounced(): void {
    // Cancel any pending timeout
    if (this.resizeTimeout) {
      clearTimeout(this.resizeTimeout);
    }

    // Cancel any pending animation frame
    if (this.rafId) {
      cancelAnimationFrame(this.rafId);
    }

    // Immediately update header height to prevent white space
    this.handleHeaderHeight();

    // Debounce additional recalculations
    this.resizeTimeout = window.setTimeout(() => {
      // Use requestAnimationFrame to ensure DOM has finished updating
      this.rafId = requestAnimationFrame(() => {
        this.handleHeaderHeight();
      });
    }, 100); // Increased debounce time for more stable recalculation
  }

  private handleSearchClick(event: Event): void {
    event.preventDefault();

    // Only toggle if the search input is not already active
    const searchInput = this.searchInput?.querySelector("uwp-search-input");
    const isSearchActive = searchInput?.classList.contains("is-active");

    if (!isSearchActive) {
      this.searchInput?.classList.add("is-open");
      // Focus the search input
      const input = this.searchInput?.querySelector("input");
      input?.focus();
    }

    this.updateTransparency();
  }

  private handleMobileMenuClick(event: Event): void {
    event.preventDefault();

    const mobileMenu = document.querySelector(
      "uwp-mobile-menu",
    ) as HTMLDivElement;

    if (!mobileMenu) return;

    const isOpen = mobileMenu.classList.contains("is-open");

    if (isOpen) {
      this.mobileMenuWrapper?.setAttribute("aria-expanded", "false");
      mobileMenu.classList.remove("is-open");
      enablePageScroll();
      this.updateTransparency();
    } else {
      this.mobileMenuWrapper?.setAttribute("aria-expanded", "true");
      mobileMenu.classList.add("is-open");
      disablePageScroll();
      this.updateTransparency();
    }
  }

  private handleMegamenuClick(event: Event): void {
    event.preventDefault();

    const trigger = event.currentTarget as HTMLButtonElement;
    const wrapper = trigger.closest("[data-megamenu-wrapper]") as HTMLElement;

    if (!wrapper) return;

    const isOpen = wrapper.classList.contains("is-open");

    if (isOpen) {
      this.closeMegamenu(wrapper);
      this.mobileMenuWrapper?.setAttribute("aria-expanded", "false");
      enablePageScroll();
    } else {
      this.closeAllMegamenus();
      this.openMegamenu(wrapper);
      this.mobileMenuWrapper?.setAttribute("aria-expanded", "true");
      disablePageScroll();
    }
  }

  private handleKeyDown(event: KeyboardEvent): void {
    if (event.key === "Escape") {
      this.closeAllMegamenus();
      this.mobileMenuWrapper?.setAttribute("aria-expanded", "false");
      enablePageScroll();
    }
  }

  private handleOutsideClick(event: Event): void {
    const target = event.target as HTMLElement;

    if (this.currentOpenMenu && !this.currentOpenMenu.contains(target)) {
      this.closeAllMegamenus();
      this.mobileMenuWrapper?.setAttribute("aria-expanded", "false");
      enablePageScroll();
    }
  }

  private openMegamenu(wrapper: HTMLElement): void {
    if (
      wrapper.classList.contains("is-opening") ||
      wrapper.classList.contains("is-open")
    ) {
      return;
    }

    const trigger = wrapper.querySelector(
      "[data-megamenu-trigger]",
    ) as HTMLButtonElement;
    const content = wrapper.querySelector(
      "[data-megamenu-content]",
    ) as HTMLElement;

    if (!trigger || !content) return;

    // Clean up any existing states
    wrapper.classList.remove("is-closing");

    // Set opening state
    wrapper.classList.add("is-opening");
    trigger.setAttribute("aria-expanded", "true");
    content.setAttribute("aria-hidden", "false");

    // Force reflow
    void wrapper.offsetHeight;

    // Set final open state
    requestAnimationFrame(() => {
      wrapper.classList.remove("is-opening");
      wrapper.classList.add("is-open");
      this.currentOpenMenu = wrapper;
      this.updateTransparency();
    });
  }

  private closeMegamenu(wrapper: HTMLElement): void {
    if (
      wrapper.classList.contains("is-closing") ||
      !wrapper.classList.contains("is-open")
    ) {
      return;
    }

    const trigger = wrapper.querySelector(
      "[data-megamenu-trigger]",
    ) as HTMLButtonElement;
    const content = wrapper.querySelector(
      "[data-megamenu-content]",
    ) as HTMLElement;

    if (!trigger || !content) return;

    // Set closing state
    wrapper.classList.add("is-closing");
    wrapper.classList.remove("is-open");
    trigger.setAttribute("aria-expanded", "false");

    // Wait for animation to complete
    setTimeout(() => {
      wrapper.classList.remove("is-closing");
      content.setAttribute("aria-hidden", "true");

      if (this.currentOpenMenu === wrapper) {
        this.currentOpenMenu = null;
      }
      this.updateTransparency();
    }, this.animationDuration);
  }

  private closeAllMegamenus(): void {
    if (this.megamenuWrappers) {
      this.megamenuWrappers.forEach((wrapper) => {
        if (wrapper.classList.contains("is-open")) {
          this.closeMegamenu(wrapper);
        }
      });
    }
  }

  public handleHeaderHeight() {
    const headerElement = this.parentElement;

    if (!headerElement) return;

    // Get the announcement bar element if it exists
    const announcementBar = document.querySelector(
      "uwp-announcement-bar",
    ) as HTMLElement;

    // Calculate heights immediately and then again after a delay
    const calculateHeight = () => {
      // Force reflow to ensure accurate measurements
      void headerElement.offsetHeight;

      // Set header height variable
      const headerHeight = headerElement.clientHeight;
      document.body.style.setProperty("--header-height", `${headerHeight}px`);

      // Set announcement bar height variable
      let announcementBarHeight = 0;
      if (announcementBar && announcementBar.offsetHeight > 0) {
        announcementBarHeight = announcementBar.offsetHeight;
      }

      // If header is sticky we treat announcement bar as collapsed
      const isHeaderSticky = headerElement.classList.contains("is-sticky");
      if (isHeaderSticky) {
        announcementBarHeight = 0;
      }
      document.body.style.setProperty(
        "--announcement-bar-height",
        `${announcementBarHeight}px`,
      );

      // Calculate combined height: header + announcement bar (if visible)
      let combinedHeight = headerHeight;

      // Only include announcement bar height if it exists, has height, and header is not sticky
      // When header is sticky, the announcement bar is visually hidden by the translate transform
      // isHeaderSticky already defined above

      if (announcementBarHeight > 0 && !isHeaderSticky) {
        combinedHeight += announcementBarHeight;
      }

      // Set the combined header group height
      document.body.style.setProperty("--header-group", `${combinedHeight}px`);
    };

    // Calculate immediately to prevent whitespace
    calculateHeight();

    // Also calculate after a small delay to handle any pending transitions
    setTimeout(calculateHeight, 10);
  }

  public handleStickyHeader() {
    const headerElement = this.parentElement;

    if (!headerElement) return;

    headerElement.classList.toggle("is-sticky", window.scrollY >= 100);
    this.handleHeaderHeight();
    this.updateTransparency();
  }

  // Helper to decide whether the header should remain transparent
  private updateTransparency(): void {
    if (!this.initialTransparent) return; // If header wasn't transparent initially, don't manage
    // If the instant search is open, ensure header is NOT transparent
    const instantSearch = document.querySelector("uwp-search-input");
    const instantSearchOpen =
      instantSearch?.classList.contains("is-active") ||
      document.body.classList.contains("search-is-open") ||
      document
        .querySelector("[js-instant-search='results-parent']")
        ?.classList.contains("is-open");
    if (instantSearchOpen) {
      this.classList.remove("is-transparent");
      return;
    }

    const anyMegamenuOpen = Array.from(this.megamenuWrappers ?? []).some((w) =>
      w.classList.contains("is-open"),
    );

    const mobileMenu = document.querySelector("uwp-mobile-menu");
    const mobileMenuOpen = mobileMenu?.classList.contains("is-open");

    const isSticky = this.parentElement?.classList.contains("is-sticky");

    const searchActive =
      document.querySelector("uwp-search-input.is-active") !== null;

    const shouldBeTransparent =
      !anyMegamenuOpen && !mobileMenuOpen && !isSticky && !searchActive;

    this.classList.toggle("is-transparent", shouldBeTransparent);
  }

  // Centralize adding global listeners that need transparency recalculation
  private entryListeners(): void {
    window.addEventListener("scroll", () => this.updateTransparency());

    // Listen for search input state changes
    document.addEventListener("search-input-state-change", (event) => {
      const customEvent = event as CustomEvent;
      if (customEvent.detail?.isActive) {
        this.searchInput?.classList.add("is-open");
      } else {
        this.searchInput?.classList.remove("is-open");
      }
      this.updateTransparency();
    });
  }
}

customElements.define("uwp-header", Header);
